INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt) SELECT id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "04088393-4152-49a7-8959-745580a742da", "product_id": "e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4", "name": "Buzzery dla drużyn", "short_description": "Jedna waliza to 4 przyciski; jeden przycisk na drużynę.", "description": "Wybierz 4, 8 lub 12 buzzerów. Uczestnicy ustalają odpowiedź w drużynie, a jej przedstawiciel używa przycisku. Przy 40–50 osobach punktem wyjścia jest 8 stanowisk i podział na około 5–6 osób w drużynie.", "display_order": 0, "is_active": true, "partner_portal_visible": false, "overrides_equipment": true, "overrides_staff": true, "offer_image_path": "assets/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4/quizzagio-20261012/buzzery.jpg", "offer_image_alt": "Waliza z czterema buzzerami Quizzagio."}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt) SELECT id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "973ee3a1-4c09-444a-bec1-92b28fe447a2", "product_id": "e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4", "name": "Program i obsługa teleturnieju", "short_description": "Prowadzący i osobny technik obsługujący QuizXpress.", "description": "Około 60 minut gry: 6 kategorii po 5 pytań, instruktaż i prezentacja wyników. Prowadzący prowadzi rozgrywkę, technik obsługuje system. Siódma kategoria indywidualna jest dodatkowo wyceniana.", "display_order": 1, "is_active": true, "partner_portal_visible": false, "overrides_equipment": true, "overrides_staff": true, "offer_image_path": "assets/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4/quizzagio-20261012/mikrofon.png", "offer_image_alt": "Mikrofon dla prowadzącego — przykład sprzętu używanego do obsługi teleturnieju."}'::jsonb);
INSERT INTO public.offer_product_variants (id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt) SELECT id,product_id,name,short_description,description,display_order,is_active,partner_portal_visible,overrides_equipment,overrides_staff,offer_image_path,offer_image_alt FROM jsonb_populate_record(NULL::public.offer_product_variants,'{"id": "941da172-cea8-491d-8a8c-cf87db7a9236", "product_id": "e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4", "name": "Ekran i podstawowe nagłośnienie", "short_description": "TV 85 cali, nagłośnienie i mikrofon dla prowadzącego.", "description": "W standardzie TV 85 cali ze stojakiem, komputer, nagłośnienie i mikrofon. Montaż, próba i demontaż w zakresie. Ekran projekcyjny lub LED oraz rozbudowa dźwięku wymagają osobnej wyceny.", "display_order": 2, "is_active": true, "partner_portal_visible": false, "overrides_equipment": true, "overrides_staff": true, "offer_image_path": "assets/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4/quizzagio-20261012/ekran.png", "offer_image_alt": "Telewizor Sony Bravia 85 cali do wyświetlania pytań i wyników."}'::jsonb);
UPDATE public.offer_products SET (name,description,offer_short_description,offer_description,public_description,offer_compact_description,service_duration_hours,extension_price_net_per_hour,offer_benefits,price_net,base_price,price_gross,vat_rate,unit,min_quantity,sales_packages_enabled,offer_page_enabled,offer_page_variant,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,product_page_url,related_service_url,related_service_label,tags,pricing_addons,offer_requirements,offer_additional_requirements,sales_packages)=(SELECT name,description,offer_short_description,offer_description,public_description,offer_compact_description,service_duration_hours,extension_price_net_per_hour,offer_benefits,price_net,base_price,price_gross,vat_rate,unit,min_quantity,sales_packages_enabled,offer_page_enabled,offer_page_variant,offer_image_path,offer_image_alt,offer_image_position_x,offer_image_position_y,offer_image_zoom,product_page_url,related_service_url,related_service_label,tags,pricing_addons,offer_requirements,offer_additional_requirements,sales_packages FROM jsonb_populate_record(NULL::public.offer_products,'{"name": "Quizzagio — teleturniej buzzerowy", "description": "Quiz drużynowy na fizycznych buzzerach i QuizXpress. Około 60 minut, 6 kategorii tematycznych po 5 pytań. Baza realizacji: 5000 zł netto; każdy buzzer: 400 zł netto. Pełne pakiety 4/8/12 buzzerów: 6600/8200/9800 zł netto. Prowadzący, technik, TV 85 cali i podstawowe nagłośnienie w cenie. Siódma kategoria personalizowana oraz logistyka wyceniane osobno.", "offer_short_description": "Około godziny gry drużynowej: 30 pytań, 6 kategorii i fizyczne buzzery.", "offer_description": "Quizzagio to quiz drużynowy na buzzerach z obsługą QuizXpress. Około 60 minut gry obejmuje 6 kategorii po 5 pytań. Jeden przycisk obsługuje jedną drużynę. Zapewniamy prowadzącego, technika, komputer, TV 85 cali i podstawowe nagłośnienie. Pakiety obejmują 4, 8 lub 12 buzzerów. Siódma kategoria z pytaniami o firmie jest opcjonalna i wyceniana osobno.", "public_description": "Quizzagio — teleturniej buzzerowy\n\nQuizzagio to prowadzony quiz drużynowy oparty na fizycznych przyciskach i oprogramowaniu QuizXpress. Uczestnicy wspólnie ustalają odpowiedź, a wyznaczona osoba używa buzzera swojej drużyny. Pytania i wyniki pojawiają się na ekranie. Prowadzący wyjaśnia zasady i prowadzi grę, a osobna osoba techniczna obsługuje system, prezentację i punktację.\n\nPrzebieg i czas\nPodstawowy program trwa około 60 minut i obejmuje około 30 pytań: 6 kategorii tematycznych po 5 pytań. Tematy oraz poziom trudności uzgadniamy przed wydarzeniem. Przed rozpoczęciem jest instruktaż i próba przycisków. Zasady zgłaszania odpowiedzi, czas na odpowiedź i punktację omawia prowadzący. Przebieg i tempo zależą również od aktywności uczestników.\n\nDrużyny i buzzery\nJeden buzzer to stanowisko jednej drużyny, a nie limit jednego uczestnika. Przy grze zespołowej proponujemy zwykle około 4–6 osób w drużynie. Liczbę drużyn dobieramy do liczby gości, ustawienia sali i oczekiwanego tempa. Dla około 40–50 osób punktem wyjścia jest pakiet 8 buzzerów: około 5–6 osób na drużynę, z dopasowaniem podziału przy 50 gościach. Gra w 4 większych drużynach obniża cenę, lecz daje mniej stanowisk i mniej okazji do samodzielnego odpowiadania. Pakiet 12 buzzerów pozwala podzielić większą grupę na 12 drużyn lub zmniejszyć zespoły.\n\nCo zawiera baza realizacji\nProwadzący teleturniej, technik/operator QuizXpress, komputer z przygotowanym programem, konfiguracja i próba systemu, podstawowy zestaw pytań, około godziny gry, prezentacja wyników, telewizor 85 cali ze stojakiem oraz podstawowe nagłośnienie z mikrofonem dla prowadzącego. Montaż i demontaż standardowego zestawu są częścią realizacji. Ekran i dźwięk służą obsłudze quizu; nie stanowią całodziennej obsługi konferencji ani koncertu.\n\nPakiety i cena\nBaza realizacji kosztuje 5 000 zł netto. Do niej doliczamy 400 zł netto za każdy używany buzzer. Jedna waliza zawiera 4 buzzery.\n• 4 buzzery / 4 drużyny / 1 waliza: 6 600 zł netto.\n• 8 buzzerów / 8 drużyn / 2 walizy: 8 200 zł netto.\n• 12 buzzerów / 12 drużyn / 3 walizy: 9 800 zł netto.\nSą to pełne ceny pakietów obejmujące bazę oraz wskazaną liczbę buzzerów. Bazy nie doliczamy ponownie. Cena zależy od liczby stanowisk, a nie od liczby osób w drużynie. Transport, parking i ewentualny nocleg ekipy kalkulujemy oddzielnie dla lokalizacji wydarzenia.\n\nOpcjonalna siódma kategoria\nNa zamówienie przygotowujemy dodatkową kategorię dopasowaną do firmy, uczestników lub tematu wydarzenia. To rozszerzenie ponad 6 kategorii i około 30 pytań podstawowych. Liczbę dodatkowych pytań, materiały od klienta, termin akceptacji i cenę ustalamy osobno. Przed potwierdzeniem określamy także, czy dodatkowa runda wydłuży program, czy zmienimy jego tempo lub zakres. Personalizacja nie jest automatycznie zawarta w cenach pakietów.\n\nEkran i warunki sali\nW standardzie zapewniamy telewizor 85 cali. Widoczność pytań wymaga odpowiedniego ustawienia stołów i odległości od ekranu; liczbę gości oceniamy razem z układem sali. Ekran projekcyjny lub LED oraz rozbudowane nagłośnienie są możliwym rozszerzeniem po indywidualnej wycenie. Potrzebujemy miejsc dla drużyn z dostępem do przycisków, stanowiska operatora, zasilania 230 V i bezpiecznego prowadzenia przewodów. Dostęp do sali, rozładunek, montaż i próbę uzgadniamy z obiektem.\n\nZakres dodatkowy\nNagrody, rozbudowana scenografia, większy ekran, dodatkowe kategorie i obsługa pozostałych części wydarzenia wymagają osobnego uzgodnienia. Termin i dostępność sprzętu potwierdzamy przy przygotowaniu oferty.", "offer_compact_description": null, "service_duration_hours": 1, "extension_price_net_per_hour": null, "offer_benefits": ["Fizyczne buzzery dla 4, 8 lub 12 drużyn", "Prowadzący i osobny operator QuizXpress", "Ekran, nagłośnienie i punktacja w standardzie", "Opcjonalna siódma kategoria o firmie"], "price_net": 6600, "base_price": 6600, "price_gross": 8118, "vat_rate": 23, "unit": "pakiet", "min_quantity": 1, "sales_packages_enabled": true, "offer_page_enabled": true, "offer_page_variant": "default", "offer_image_path": "assets/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4/quizzagio-20261012/buzzery.jpg", "offer_image_alt": "Waliza Quiz Master zawierająca cztery fizyczne buzzery do teleturnieju Quizzagio.", "offer_image_position_x": 50, "offer_image_position_y": 50, "offer_image_zoom": 0.85, "product_page_url": "https://mavinci.pl/produkty/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4", "related_service_url": "https://mavinci.pl/oferta/quizy-teleturnieje", "related_service_label": "Quizy i teleturnieje — poznaj usługę", "tags": ["quiz drużynowy", "teleturniej buzzerowy", "QuizXpress", "integracja firmowa"], "pricing_addons": [{"id": "53e76a48-3e8b-495c-8241-2bb214f45527", "name": "Siódma kategoria indywidualna", "kind": "quantity", "unit": "usługa", "enabled": false, "quantity": 0, "included_quantity": 0, "unit_price": 0, "price_on_request": true, "description": "Dodatkowa kategoria poza 6 kategoriami podstawowymi. Temat, liczbę pytań, materiały, czas programu i cenę uzgadniamy przed realizacją."}, {"id": "564811cd-541c-4fb6-8a92-85c7e67dda10", "name": "Większy ekran — projekcja lub LED", "kind": "quantity", "unit": "usługa", "enabled": false, "quantity": 0, "included_quantity": 0, "unit_price": 0, "price_on_request": true, "description": "Zmiana standardowego TV 85 cali na uzgodniony zestaw projekcyjny lub ekran LED. Dopłata obejmuje różnicę zakresu, bez ponownego naliczania standardowego ekranu."}], "offer_requirements": [], "offer_additional_requirements": [{"id": "04e89b27-4152-4072-b830-97a9d3a1b798", "title": "UKŁAD DRUŻYN", "category": "place", "description": "Jeden buzzer na drużynę. Miejsca przy stołach z widokiem na ekran, przestrzeń dla prowadzącego i operatora oraz bezpieczne prowadzenie przewodów."}, {"id": "5fda9bea-1a66-40c7-aae0-c3f3dbf9564f", "title": "ZASILANIE", "category": "power", "description": "Sprawne zasilanie 230 V dla komputera, ekranu i nagłośnienia. Dostęp oraz trasy kablowe uzgadniamy z obiektem."}, {"id": "7a39679a-32fc-46d7-8f5d-aa4eb788934c", "title": "MONTAŻ I PRÓBA", "category": "setup", "description": "Standardowo planujemy 90 minut na montaż i próbę oraz 45 minut na demontaż. Godziny dostępu do sali i rozładunku potwierdzamy przed realizacją."}, {"id": "7fca7e39-884c-4d61-997f-94ba2bf7ca6e", "title": "PROGRAM QUIZU", "category": "schedule", "description": "Około 60 minut, 6 kategorii po 5 pytań. Tematy i poziom trudności ustalamy przed wydarzeniem. Dodatkowa siódma kategoria wymaga osobnego uzgodnienia ceny i czasu."}, {"id": "0d73a110-0f93-497e-91ad-de12fa086f05", "title": "LICZBA BUZZERÓW", "category": "resources", "description": "4, 8 lub 12 buzzerów zależnie od pakietu; 4 w każdej walizie. Technik przygotowuje konfigurację QuizXpress, połączenia i próbę wszystkich stanowisk."}, {"id": "2705ad32-c900-479c-ade8-dcac201331c0", "title": "LOGISTYKA I ROZSZERZENIA", "category": "other", "description": "Dojazd, parking i ewentualny nocleg ekipy kalkulujemy osobno. Nagrody, personalizowana kategoria i większy ekran nie są automatycznie częścią pakietu."}], "sales_packages": [{"id": "bd6fb886-6495-40fa-9f12-cd1a83fbbcd1", "name": "4 buzzery — 4 drużyny", "description": "Najniższa cena: cztery drużyny i wspólna obsługa całej gry.", "included_label": "4 buzzerów · 1 waliza · ok. 60 min · pełna baza realizacji", "element_ids": ["04088393-4152-49a7-8959-745580a742da", "973ee3a1-4c09-444a-bec1-92b28fe447a2", "941da172-cea8-491d-8a8c-cf87db7a9236"], "price_net": 6600, "bonus": "", "highlighted": false, "image_path": "assets/e06123c9-ca6a-5bbe-ad0f-1d4c2b3414b4/quizzagio-20261012/buzzery.jpg", "image_alt": "Waliza z czterema buzzerami. Pakiet obejmuje 1 walizy i łącznie 4 buzzerów.", "extension_price_net_per_hour": null, "cost_items": null, "resources": {"equipment": [{"id": "92c3736d-7ee0-4db5-8c4f-e47fc6bb16c8", "name": "Telewizor TV SONY BRAVIA 85\"", "equipment_